#!/bin/bash
# Package the per-target static libraries into a framework-bundle XCFramework
# (the canonical modular binary layout — same shape build_ios.sh produces):
#
#   <slice>/<module>.framework/
#       <module>                    static archive (bundle name == module name)
#       Headers/*.h                 public headers + <lib>.h generated umbrella
#       Modules/module.modulemap    framework module <module> { umbrella header }
#       Info.plist
#
# Usage: create_xcframework.sh <lib-name>      (opencore-amrnb | opencore-amrwb)
# Expects the per-target install trees under ${OUTPUT_DIR}/<platform>-<arch>-<sdk>/
# (the local build_ios.sh layout; in CI the downloaded job artifacts are
# flattened into it by the workflow before this script runs).
set -euo pipefail

lib_name="${1:?usage: create_xcframework.sh <lib-name>}"
OUTPUT_DIR="${OUTPUT_DIR:-${GITHUB_WORKSPACE:-$(pwd)}/output}"

# Clang module names cannot contain '-': opencore-amrnb -> opencore_amrnb
module_name="${lib_name//-/_}"

case "${lib_name}" in
    opencore-amrnb) headers="interf_dec.h interf_enc.h" ;;
    opencore-amrwb) headers="dec_if.h if_rom.h" ;;
    *) echo "unknown library: ${lib_name}" >&2; exit 1 ;;
esac

# Framework bundle version — kept in sync with configure.ac's AC_INIT.
VERSION="${VERSION:-0.1.6}"

die() { echo "error: $*" >&2; exit 1; }

# Stage headers from the make-install tree — guarantees the shipped headers
# match the built library.
installed="${OUTPUT_DIR}/iphoneos-arm64-iPhoneOS/include/${lib_name}"
stage="${OUTPUT_DIR}/staging/${lib_name}"
rm -rf "${stage}" "${OUTPUT_DIR}/${lib_name}.xcframework"
mkdir -p "${stage}/headers"
for h in ${headers}; do
    [ -f "${installed}/${h}" ] || die "missing installed header: ${installed}/${h}"
    cp -p "${installed}/${h}" "${stage}/headers/"
done

# Generated umbrella header: single textual entry point
# (#include <module>/<lib>.h) and the module's umbrella.
guard="$(printf '%s' "${lib_name}" | tr '[:lower:]-' '[:upper:]_')_H"
{
    echo "/* Umbrella header for ${lib_name} (module ${module_name}). Generated by create_xcframework.sh. */"
    echo "#ifndef ${guard}"
    echo "#define ${guard}"
    echo ""
    for h in ${headers}; do echo "#include \"${h}\""; done
    echo ""
    echo "#endif /* ${guard} */"
} > "${stage}/headers/${lib_name}.h"

# Assemble one static framework bundle per platform variant. Bundle name ==
# clang module name (underscores) so module import and autolinking agree.
for variant in iphoneos iphonesimulator macosx; do
    case "${variant}" in
        iphoneos)
            archive="${OUTPUT_DIR}/iphoneos-arm64-iPhoneOS/lib/lib${lib_name}.a" ;;
        iphonesimulator)
            # create-xcframework takes exactly one binary per platform+variant:
            # merge the per-arch archives into one fat archive first.
            archive="${OUTPUT_DIR}/fat/${lib_name}-iphonesimulator/lib${lib_name}.a"
            rm -rf "$(dirname "${archive}")"; mkdir -p "$(dirname "${archive}")"
            lipo -create \
                "${OUTPUT_DIR}/iphonesimulator-x86_64-iPhoneSimulator/lib/lib${lib_name}.a" \
                "${OUTPUT_DIR}/iphonesimulator-arm64-iPhoneSimulator/lib/lib${lib_name}.a" \
                -output "${archive}" ;;
        macosx)
            archive="${OUTPUT_DIR}/fat/${lib_name}-macosx/lib${lib_name}.a"
            rm -rf "$(dirname "${archive}")"; mkdir -p "$(dirname "${archive}")"
            lipo -create \
                "${OUTPUT_DIR}/macosx-x86_64-MacOSX/lib/lib${lib_name}.a" \
                "${OUTPUT_DIR}/macosx-arm64-MacOSX/lib/lib${lib_name}.a" \
                -output "${archive}" ;;
    esac
    [ -f "${archive}" ] || die "missing archive: ${archive}"

    bundle="${stage}/${variant}/${module_name}.framework"
    mkdir -p "${bundle}/Headers" "${bundle}/Modules"
    cp -p "${stage}/headers/"*.h "${bundle}/Headers/"
    cp -p "${archive}" "${bundle}/${module_name}"

    # The ONE module map. Inside a *.framework bundle, clang resolves the bare
    # umbrella name against Headers/ automatically (framework module semantics)
    # — no Headers/module.modulemap copy is needed or wanted.
    {
        echo "framework module ${module_name} {"
        echo "    umbrella header \"${lib_name}.h\""
        echo "    export *"
        echo "}"
    } > "${bundle}/Modules/module.modulemap"

    printf '%s\n' \
        '<?xml version="1.0" encoding="UTF-8"?>' \
        '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">' \
        '<plist version="1.0">' \
        '<dict>' \
        "	<key>CFBundleIdentifier</key><string>com.opencore.${module_name}</string>" \
        "	<key>CFBundleName</key><string>${module_name}</string>" \
        "	<key>CFBundlePackageType</key><string>FMWK</string>" \
        "	<key>CFBundleShortVersionString</key><string>${VERSION}</string>" \
        "	<key>CFBundleVersion</key><string>${VERSION}</string>" \
        '</dict>' \
        '</plist>' > "${bundle}/Info.plist"
done

xcodebuild -create-xcframework \
    -framework "${stage}/iphoneos/${module_name}.framework" \
    -framework "${stage}/iphonesimulator/${module_name}.framework" \
    -framework "${stage}/macosx/${module_name}.framework" \
    -output "${OUTPUT_DIR}/${lib_name}.xcframework"

# Structure sanity: every slice must carry the bundle, binary, both header
# kinds and the single module map.
for slice in "${OUTPUT_DIR}/${lib_name}.xcframework"/*/; do
    [ -d "${slice}" ] || continue
    fw="${slice}${module_name}.framework"
    [ -f "${fw}/${module_name}" ]                  || die "${slice}: missing framework binary"
    [ -f "${fw}/Modules/module.modulemap" ]        || die "${slice}: missing Modules/module.modulemap"
    [ -f "${fw}/Headers/${lib_name}.h" ]           || die "${slice}: missing umbrella header"
    [ ! -e "${fw}/Headers/module.modulemap" ]      || die "${slice}: unexpected second module map"
    plutil -lint "${fw}/Info.plist" >/dev/null
done

echo "created ${OUTPUT_DIR}/${lib_name}.xcframework (framework-bundle style, module ${module_name})"
